#include <cstdint>
#include <format>
#include <iostream>
#include <queue>
#include <vector>

struct Scan {
  std::int64_t seq = 0;
  std::vector<float> ranges;
};

int main() {
  constexpr std::int64_t kBeams = 360;
  constexpr std::int64_t kScans = 20'000;
  std::queue<Scan> backlog;  // no bound: push always succeeds
  for (std::int64_t seq = 0; seq < kScans; ++seq) {
    backlog.push({.seq = seq, .ranges = std::vector<float>(kBeams)});
  }
  const std::int64_t bytes = std::ssize(backlog) * kBeams * static_cast<std::int64_t>(sizeof(float));
  std::cout << std::format("{} scans queued, nothing consumed: {} bytes of range data\n", backlog.size(), bytes);
  std::cout << std::format("the same run with a queue bounded at 8 would hold {} bytes\n",
                           8 * kBeams * static_cast<std::int64_t>(sizeof(float)));
}

mutable std::mutex mutex_;
std::condition_variable not_full_;   // waited on by producers: there is room
std::condition_variable not_empty_;  // waited on by consumers: there is an item
std::deque<T> items_;
std::ptrdiff_t capacity_ = 0;
bool closed_ = false;

#include <condition_variable>
#include <cstdint>
#include <deque>
#include <format>
#include <iostream>
#include <mutex>
#include <optional>
#include <thread>
#include <utility>

// A queue with room for `capacity` items. Producers block while it is full, consumers while it is empty,
// and close() ends both waits for good.
template <typename T>
class BoundedQueue {
 public:
  explicit BoundedQueue(std::ptrdiff_t capacity) : capacity_(capacity) {}

  // False once the queue is closed; otherwise it waits for room and hands the item over.
  [[nodiscard]] bool push(T item) {
    {
      std::unique_lock<std::mutex> lock(mutex_);
      not_full_.wait(lock, [this] { return closed_ || std::ssize(items_) < capacity_; });
      if (closed_) return false;
      items_.push_back(std::move(item));
    }
    not_empty_.notify_one();
    return true;
  }

  // No value once the queue is closed and empty; otherwise it waits for an item.
  [[nodiscard]] std::optional<T> pop() {
    std::optional<T> item;
    {
      std::unique_lock<std::mutex> lock(mutex_);
      not_empty_.wait(lock, [this] { return closed_ || !items_.empty(); });
      if (items_.empty()) return std::nullopt;
      item = std::move(items_.front());
      items_.pop_front();
    }
    not_full_.notify_one();
    return item;
  }

  // Never waits: false when the queue is full or closed.
  [[nodiscard]] bool try_push(T item) {
    {
      const std::lock_guard<std::mutex> lock(mutex_);
      if (closed_ || std::ssize(items_) >= capacity_) return false;
      items_.push_back(std::move(item));
    }
    not_empty_.notify_one();
    return true;
  }

  // Stop accepting items. Consumers drain what is left, then get no value.
  void close() {
    {
      const std::lock_guard<std::mutex> lock(mutex_);
      if (closed_) return;
      closed_ = true;
    }
    not_empty_.notify_all();
    not_full_.notify_all();
  }

  [[nodiscard]] std::ptrdiff_t size() const {
    const std::lock_guard<std::mutex> lock(mutex_);
    return std::ssize(items_);
  }

  [[nodiscard]] bool closed() const {
    const std::lock_guard<std::mutex> lock(mutex_);
    return closed_;
  }

 private:
  mutable std::mutex mutex_;
  std::condition_variable not_full_;   // waited on by producers: there is room
  std::condition_variable not_empty_;  // waited on by consumers: there is an item
  std::deque<T> items_;
  std::ptrdiff_t capacity_ = 0;
  bool closed_ = false;
};

struct Scan {
  std::int64_t seq = 0;
};

int main() {
  BoundedQueue<Scan> queue(2);
  std::cout << std::format("empty: size {}, closed {}\n", queue.size(), queue.closed());
  const bool first = queue.push({.seq = 1});
  const bool second = queue.push({.seq = 2});
  const bool third = queue.try_push({.seq = 3});  // the queue is full, so this one fails instead of waiting
  std::cout << std::format("push 1: {}, push 2: {}, try_push 3 into a full queue: {}\n", first, second, third);
  std::cout << std::format("pop gives {}\n", queue.pop().value().seq);
  const bool room_now = queue.try_push({.seq = 3});  // one call per statement: argument order is unspecified
  std::cout << std::format("try_push 3 now: {}, size {}\n", room_now, queue.size());

  queue.close();
  std::cout << std::format("after close: push 4: {}\n", queue.push({.seq = 4}));
  std::cout << std::format("after close: try_push 4: {}\n", queue.try_push({.seq = 4}));
  std::cout << std::format("draining: {}\n", queue.pop().value().seq);
  std::cout << std::format("draining: {}\n", queue.pop().value().seq);
  std::cout << std::format("the next pop gives {}\n", queue.pop().has_value() ? "an item" : "no value");

  // One producer, one consumer, a queue two items deep: the producer blocks, nothing is lost.
  BoundedQueue<Scan> pipe(2);
  std::int64_t received = 0;
  std::int64_t sum = 0;
  {
    std::jthread consumer([&pipe, &received, &sum] {
      while (const std::optional<Scan> scan = pipe.pop()) {
        ++received;
        sum += scan.value().seq;
      }
    });
    for (std::int64_t seq = 1; seq <= 1000; ++seq) {
      if (!pipe.push({.seq = seq})) break;
    }
    pipe.close();
  }
  std::cout << std::format("1000 scans through a queue of 2: received {}, sum {}\n", received, sum);
}

