template <typename T>
class BoundedQueue {
 public:
  explicit BoundedQueue(std::ptrdiff_t capacity) : capacity_(capacity) {}

  [[nodiscard]] bool push(T item) {
    {
      std::unique_lock<std::mutex> lock(mutex_);
      not_full_.wait(lock, [this] { return closed_ || std::ssize(items_) < capacity_; });
      if (closed_) return false;
      items_.push_back(std::move(item));
    }
    not_empty_.notify_one();
    return true;
  }

  [[nodiscard]] std::optional<T> pop() {
    std::optional<T> item;
    {
      std::unique_lock<std::mutex> lock(mutex_);
      not_empty_.wait(lock, [this] { return closed_ || !items_.empty(); });
      if (items_.empty()) return std::nullopt;
      item = std::move(items_.front());
      items_.pop_front();
    }
    not_full_.notify_one();
    return item;
  }

  void close() {
    {
      const std::lock_guard<std::mutex> lock(mutex_);
      if (closed_) return;
      closed_ = true;
    }
    not_empty_.notify_all();
    not_full_.notify_all();
  }

  [[nodiscard]] std::ptrdiff_t size() const {
    const std::lock_guard<std::mutex> lock(mutex_);
    return std::ssize(items_);
  }

 private:
  mutable std::mutex mutex_;
  std::condition_variable not_full_;
  std::condition_variable not_empty_;
  std::deque<T> items_;
  std::ptrdiff_t capacity_ = 0;
  bool closed_ = false;
};

constexpr std::int64_t kProducers = 4;
constexpr std::int64_t kConsumers = 3;
constexpr std::int64_t kPerProducer = 500;

struct Command {
  std::int64_t id = 0;
};

int main() {
  constexpr std::ptrdiff_t kCapacity = 8;
  BoundedQueue<Command> queue(kCapacity);
  std::vector<std::vector<std::int64_t>> received(kConsumers);  // one vector per consumer: no sharing
  std::ptrdiff_t high_water = 0;
  {
    std::jthread watcher([&queue, &high_water] {
      for (int k = 0; k < 50'000; ++k) high_water = std::max(high_water, queue.size());
    });
    std::vector<std::jthread> consumers;
    consumers.reserve(kConsumers);
    for (std::int64_t c = 0; c < kConsumers; ++c) {
      consumers.emplace_back([&queue, mine = &received[c]] {
        while (const std::optional<Command> command = queue.pop()) mine->push_back(command.value().id);
      });
    }
    {
      std::vector<std::jthread> producers;
      producers.reserve(kProducers);
      for (std::int64_t p = 0; p < kProducers; ++p) {
        producers.emplace_back([&queue, p] {
          for (std::int64_t k = 0; k < kPerProducer; ++k) {
            if (!queue.push({.id = p * kPerProducer + k})) return;
          }
        });
      }
    }
    queue.close();  // every producer has finished; the consumers drain and then stop
  }

  std::vector<std::int64_t> all;
  for (const std::vector<std::int64_t>& mine : received) all.insert(all.end(), mine.begin(), mine.end());
  std::ranges::sort(all);
  const std::int64_t expected = kProducers * kPerProducer;
  std::vector<std::int64_t> wanted(expected);
  std::iota(wanted.begin(), wanted.end(), 0);
  std::cout << std::format("{} commands sent, {} received, queue left with {}\n", expected, std::ssize(all),
                           queue.size());
  std::cout << std::format("every command exactly once: {}\n", all == wanted);
  std::cout << std::format("a watcher sampled the size 50000 times and never saw more than {}: {}\n", kCapacity,
                           high_water <= kCapacity);

  // Closing while every consumer is waiting on an empty queue.
  BoundedQueue<Command> idle(8);
  std::vector<int> woke(kConsumers, 0);
  {
    std::vector<std::jthread> consumers;
    consumers.reserve(kConsumers);
    for (std::int64_t c = 0; c < kConsumers; ++c) {
      consumers.emplace_back([&idle, flag = &woke[c]] {
        const std::optional<Command> command = idle.pop();
        *flag = command.has_value() ? 0 : 1;
      });
    }
    std::this_thread::sleep_for(std::chrono::milliseconds(20));
    idle.close();
  }
  std::cout << std::format("{} consumers waiting on an empty queue, {} woke with no value\n", kConsumers,
                           std::ranges::count(woke, 1));
}

[[nodiscard]] bool push(T item) {
  {
    std::unique_lock<std::mutex> lock(mutex_);
    ready_.wait(lock, [this] { return closed_ || std::ssize(items_) < capacity_; });
    if (closed_) return false;
    items_.push_back(std::move(item));
  }
  ready_.notify_one();  // may wake the other producer, which has nothing to do
  return true;
}

void close() {
  const std::lock_guard<std::mutex> lock(mutex_);
  closed_ = true;  // wrong: nobody is told
}

void cancel() {
  {
    const std::lock_guard<std::mutex> lock(mutex_);
    closed_ = true;
    items_.clear();  // discard rather than drain
  }
  not_empty_.notify_all();
  not_full_.notify_all();
}

[[nodiscard]] std::ptrdiff_t size() const {
  return std::ssize(items_);  // wrong: read without the mutex
}
